int mindist(int *arr, int n, int x, int y)
{
    int d = 100;

    for(int i = 0 ; i < n ; i++)
    {
        if(x == *(arr + i))
        {
            for(int j = i ; j < n ; j++)
            {
                if(y == *(arr + j) && d > (j - i))
                {
                    d = j - i ;
                }
            }
        }
    }
    return d;
}
