        a = abs(a);
        flag_a++;
    } else if(b < 0){
        b = abs(b);
        flag_b++;
    }

    if(a < b){
        tmp = a;
        a = b;
        b = tmp;
    }

    *c = a;

    while(1){
        *c += a;
        i++;

        if(i == b){
            break;
        }
