typedef struct x
{
    struct x* prev;
    int data;
    struct x* next;
}node;
void sort_insertion(node** head, int n)
{
    node* dll=(node*)malloc(sizeof(node));
    dll->data=n;
    dll->next=NULL;
    dll->prev=NULL;
    if(*head==NULL)
        *head=dll;
    else if(dll->data <= (*head)->data)
    {
        (*head)->prev=dll;
        dll->next=*head;
        *head=dll;
    }
    else
    {
        node* temp=*head;
        while(temp->next != NULL && temp->next->data < dll->data)
            temp=temp->next;
        dll->prev=temp;
        dll->next=temp->next;
        temp->next=dll;
        if(dll->next!=NULL)
            dll->next->prev=dll;
    }
}
void seq_insertion(node** head, int n)
{
    node* dll=(node*)malloc(sizeof(node));
    dll->data=n;
    dll->next=*head;
    dll->prev=NULL;
    if (*head!=NULL)
        (*head)->prev=dll;
    *head=dll;
}
node* search_node(node* head, int n) 
{
    node* dll=head;
    while (dll!=NULL)
    {
        if(dll->data==n)
            return dll;
        dll=dll->next;
    }
    return NULL;
}
void deletion(node** head, node* del)
{
    if (*head==del)
        *head=del->next;
    else 
    {
        if (del->next!=NULL)
            del->next->prev=del->prev;
        if (del->prev!=NULL)
            del->prev->next=del->next;
    }
    free(del);
}
void printforward(node* head)
{
    node* dll=head;
    while (dll!=NULL)
    {
        printf("%d  ",dll->data);
        dll=dll->next;
    }
}
void printreversed(node* head)
{
    node* dll=head;
    while (dll->next!=NULL)
        dll=dll->next;
    while(dll!=NULL)
    {
        printf("%d  ",dll->data);
        dll=dll->prev;
    }
}
