int search_shift(int a[],int n)
{
    int str = 0;
    int end = n-1;
    int mid = (end + str)/2;
    if(a[n-1] > a[str])
    {
        return 0;
    }
    while(end>str)
    {
        mid = (end+str)/2;
        if(a[mid-1]> a[mid]){
            return mid;
        }
        else if(a[mid-1]<=a[mid] && a[mid]<=a[end])
        {
            end = mid;
        }
        else if(a[mid - 1]<= a[mid] && a[mid]>=a[end])
        {
            str = mid;
        }
    }
    return 0;

}
