int isSparse(int arr[10][10], int rows, int cols)
{
    int count=0;
    int i=0;
    int j=0;

    for(i=0; i<rows; i++)
    {
        for(j=0; j<cols; j++)
        {
            if(arr[i][j] == 0)
                count++;
            else
                continue;
        }
    }

    if(count > (rows*cols))
        return 1;
    else
        return 0;
}
