void transpose_and_display(int matrix[R][C])
{
    int rows = R;
    int columns = C;
    int i, j, temp = 0;
    int output_matrix[R][C];


    temp = columns;
    columns = rows;
    rows = temp;


    for(i=0; i<rows; i++)
    {
        for(j=0; j<columns; j++)
        {   
            output_matrix[i][j] = matrix[j][i];
        }
    }


    printf("\nTransposed Matrix is as follows:- \n");
    display(output_matrix);
}


