float powerOfTwo(int n){
    float result = 1;
    if(n >= 0){
        for(int i = 0; i < n; i++){
            result = result * 2;
        }
    } else {
        for(int i = 0; i > n; i--){
            result = result * 2;
        }
        result = 1 / result;
    }
    return result;
}
