    for (int i = 0; seq[i] != 0; i++)
    {
        qtd = 0;
        for (int j = i; seq[j] == seq[i]; j++)
        {
            qtd++;
        }

        i += qtd - 1;
        tam[k] = qtd;
        seq_aux[k] = seq[i];
        k++;
    }

    for (int i = 0, j = 0, a = 0; j < k; a++)
    {
        if (a % 2 == 0)
        {
            seq[a] = tam[i];
            i++;
        }

        else if (a % 2 != 0)
        {
            seq[a] = seq_aux[j];
            j++;
        }

        if (print == true)
        {
            printf("%i", seq[a]);
        }
    }
}

