void elemswap(int *x,int *y)
{
    int temp;
    temp=*x;
    *x=*y;
    *y=temp;
}
int sort(int a[],int l,int r)
{
    int key,start,end;
    key=a[l];
    start=l;
    end=r;
    if(start<end)
    {
        if(a[start]<=key)
        {
            start++;
        }
        if(a[end]>key)
        {
            end--;
        }
        if(start<end)
        {
            elemswap(&a[start],&a[end]);
        }
    }
    elemswap(&a[end],&a[l]);
    return end;
}
void quicksort(int a[],int l,int r)
{
    int loc;
    if(l<r)
    {
        loc=sort(a,l,r);
        quicksort(a,l,loc);
        quicksort(a,loc+1,r);
    }
}
void printarray(int a[],int n)
{
    int i;
    for(i=0;i<n;i++)
        printf("%d\t",a[i]);
}
