int binsearch(int x, int v[], int n){
  int low, high, mid;

  low = 0;
  high = n-1;
  while(low <= high){
    mid = (low+high) /2;
    if(x < v[mid])
      high = mid - 1;
    else if(x > v[mid])
      low = mid + 1;
    else 
      return mid;
  }
  return -1; 
}



int binsearchv2(int x, int v[], int n){
  int low, high, mid;

  low = 0;
  high = n-1;
  while(low < high){
    mid = (low+high)/2;
    if(x < v[mid])
      high = mid-1;
    else
      low = mid+1;
  }


  if(v[low-1] == x)
    return low-1;
  else if(v[low] == x)
    return low;
  else if(v[low+1] == x)
    return low+1;

  return -1; 
}

void selection_sort(int a[], int n){
  int smallest;
  int k;

  for(int i = 0; i < n - 1; i++){
    smallest = a[i];
    k = i;
    for(int j = i+1; j < n; j++)
      if(a[j] < smallest){
    smallest = a[j];
    k = j;
      }
    if(i != k)
      change(a, i, k);
  }
}

void change(int a[], int b, int c){
  int aux = a[b];
  a[b] = a[c];
  a[c] = aux;
}
