    if(ns[i] != 0)
      printf("%d", ns[i]);
  printf("\n");
}



void change(int vector[], int i, int j){
  int aux;

  aux = vector[i];
  vector[i] = vector[j];
  vector[j] = aux;
}

void quicksort(int vector[], int inf, int sup){
  int i, j, x;

  i = inf;
  j = sup;
  x = vector[(i+j)/2];

  while(i <= j){ 
      while(vector[i] < x)    
    i++;
      while(vector[j] > x)  
    j--;
      if(i<=j){
    change(vector, i, j);
    i++;
    j--;
      }
  }

  if(inf < j)
    quicksort(vector, inf, j);
  if(i < sup)
    quicksort(vector, i, sup);
}
