{
    return(key%10);
}
void insert(int key,int value)
{
    int index=H(key);
    struct hash* p=(struct hash*)malloc(sizeof(struct hash));
    p->val=value;
    p->next=NULL;
    if(HASH[index]==NULL)
    {
        HASH[index]=p;
    }
    else
    {
        temp=HASH[index];
        while(temp->next!=NULL)
            temp=temp->next;
        temp->next=p;
    }
}
void delete(int key,int value)
{
    int index=H(key);
    int ct=0;
    if(HASH[index]!=NULL)
    {
        temp=HASH[index];
        q=temp;
        while(temp->next!=NULL)
        {
            if(temp->val==value)
            {
                if(temp==HASH[index])
                {
                    HASH[index]=temp->next;
                    free(temp);
                    temp=HASH[index];
                    printf("\nValue deleted");
                    ct++;
                }
                else
                {
                    q->next=temp->next;
                    free(temp);
                    printf("\nValue deleted");
                    ct++;
                }
            }
            q=temp;
            temp=temp->next;
        }
        if(temp->val==value)
        {
            q->next=NULL;
            free(temp);
            printf("\nValue deleted");
            ct++;
        }
        if(ct==0)
        printf("\nValue is not found");
    }
}
void search(int key,int value)
{
    int index=H(key);
    int ct=0;
    if(HASH[index]!=NULL)
    {
        temp=HASH[index];
        while(temp->next!=NULL)
        {
            if(temp->val==value)
            {
                printf("\nValue found");
                ct++;
            }
            temp=temp->next;
        }
        if(temp->val==value)
        {
            printf("\nValue found");
            ct++;
        }
        if(ct==0)
        printf("\nValue not found");
    }
}
