        numero=9;
        break;
    }
    return numero;
}
bool verificarCaptchaMatematico(char *conta, int resultado){

    int resultadoReal, valorA, valorB, simbolo;

    valorA=real(conta[0]);
    valorB=real(conta[2]);
    simbolo=conta[1];

    if (conta[1]==42){
        resultadoReal=valorA*valorB;
    } else {
        resultadoReal=valorA+valorB;
    }

    if (resultadoReal==resultado) {
        return TRUE;
    } else {
        return FALSE;
    }

}
