            strcpy(verificador[6],"3");
            break;
    }

    return novoCaptcha;
}
int buscaTipo(char palavra[20]){
    int tipo, cont;

    for(cont=0;cont<15;cont++){
        if (strcmp(palavras[cont].nome,palavra)==0) {
            return palavras[cont].tipo;
            break;
        }
    }

    return FALSE;
}
