                contInteira++;
            }
            else
            {
                valorPagar = entradaInteira / 2;
                printf("\nValor a pagar: %g", valorPagar);
                contMeia++;
            }


            while(ingressoComprado == 0)
            {
                printf("\n\nForma de Pagamento:\n");
