                    totalPagar = pagamento - valorPagar;

                    if(totalPagar < 0)
                    {
                        printf("\nValor menor que valor total do ingresso\n\n");
                    }
                    else 
                    {
                        printf("\ntroco eh: %g", totalPagar);
