    printf("\nPrograma para calcular Cos(x) mediante sumas de Taylor\nIngresa X:");
    scanf("%i", &X);
    printf("\nIngrse el numero de sumas: ");
    scanf("%i", &veces);
    double Suma_total = 0.0;
    int i=1;
    do{
        if(i%2 == 0)
            Suma_total += (Exp(X, i*2) / Fac(i*2));
        else
            Suma_total -= (Exp(X, i*2) / Fac(i*2));
        ++i;
    }while(i <= veces);
    printf("cos(%i) es igual a %lf", X, (Suma_total + 1.0));

    return 0;
